"use strict";(globalThis.webpackChunklinux_cleanup_docs||=[]).push([[2262],{48521(e){e.exports=JSON.parse('{"tag":{"label":"safety","permalink":"/tags/safety","allTagsPath":"/tags","count":6,"items":[{"id":"safety/irreversibility","title":"Deletion is permanent","description":"linux-cleanup has no undo, no trash, and no backup step. What that means in practice, why it was designed that way, and what your options actually are afterwards.","permalink":"/safety/irreversibility"},{"id":"faq","title":"FAQ","description":"Common questions about linux-cleanup \u2014 whether it can delete your code, whether it phones home, why there is no undo, how often to run it, and what it will not do.","permalink":"/faq"},{"id":"safety/preview-first","title":"Preview before deleting","description":"linux-cleanup has no --dry-run flag. Use --scan, --list-targets and --self-test to see exactly what would be removed before anything is deleted.","permalink":"/safety/preview-first"},{"id":"reference/protected-paths","title":"Protected paths","description":"The complete verified list of paths linux-cleanup refuses to delete \u2014 system roots, personal directories, package-manager install roots, and shell-init filenames.","permalink":"/reference/protected-paths"},{"id":"safety/guards","title":"Safety guards","description":"The four independent gates a path must clear before linux-cleanup deletes it \u2014 the path allowlist, the staleness gate, interactive-only personal modes, and sudo confinement.","permalink":"/safety/guards"},{"id":"safety/what-it-deletes","title":"What it deletes","description":"The complete list of what linux-cleanup removes, grouped by category, with typical sizes, regeneration cost, and which paths it refuses to touch at all.","permalink":"/safety/what-it-deletes"}],"unlisted":false}}')}}]);